NIHSX001.ol:
# SoloHI FSW Bank Boot
VAR_PROMBANK := 99;
VAR_FSWBANK := 0;
VAR_EVENBOOT := (NIH0TBCT % 2); # 0 if bootcount is event

if (VAR_EVENBOOT == 0) then
   # Boot Count is EVEN
   # PROM BANK 1
    VAR_PROMBANK := 1;

    # comparison in IF doesn't seem to work; here's a workaround
    VAR_LOG9DIFF := (NIHXTBL9 - 2879389698); 
    VAR_LOG6DIFF := (NIHXTBL6 - 2879389698);

   # Which FSW Bank?
   if ((VAR_LOG9DIFF == 0) lor (VAR_LOG6DIFF == 0)) then
      # Bank 1 FSW error flag set or Bank 1 checksum error
      VAR_FSWBANK := 2;
   else
      # Bank 1 is OK
      VAR_FSWBANK := 1;
   endif;
else
   # BOOT COUNT IS ODD
   VAR_PROMBANK := 2;

    # comparison in IF doesn't seem to work; here's a workaround
   VAR_LOG6DIFF := (NIHXTBL6 - 2879389697);
   VAR_LOG3DIFF := (NIHXTBL3 - 2879389697);

   if ((VAR_LOG6DIFF == 0) lor (VAR_LOG3DIFF == 0)) then
      # Bank 2 FSW error flag set or Bank 2 checksum error
      VAR_FSWBANK := 1;
   else
      # Bank 2 is OK
      VAR_FSWBANK := 2;
   endif;
endif;

return(VAR_FSWBANK);

NSMXS011.ol:
#Global Variables
#GVAR_SSMM_M2_LastSampleTime
#GVAR_SSMM_M2_LastSampleVal
#GVAR_SSMM_M2_LastGradient
#GVAR_SSMM_M2_Ok
#
# Local Variables
# CONFIG
VAR_CycleTime := 1015.0;       # SSMM scrubbing cycle time
VAR_CycleMultiplier := 1.05;   # Multiplier, to avoid aliasing
VAR_LowerLim := 0.13;          # Lowest point at which we go OOL       
VAR_UpperLim := 0.2;           # Upper cut-off
# SSMM Memory Module Error Count TM
VAR_SSMM_M2_SampleTime := OPMCS_utc2obt(NSM00800.time) * 1.0;
VAR_SSMM_M2_SampleVal := NSM00800.raw;
#
# Sanity Checks on Globals
if (GVAR_SSMM_M2_LastSampleTime < 1.0) lor (GVAR_SSMM_M2_LastSampleTime > VAR_SSMM_M2_SampleTime) then
    GVAR_SSMM_M2_LastSampleTime := VAR_SSMM_M2_SampleTime;
    GVAR_SSMM_M2_LastSampleVal := VAR_SSMM_M2_SampleVal;
    GVAR_SSMM_M2_Gradient := 0.0;
    GVAR_SSMM_M2_Ok := 0;
    return(GVAR_Ok);
endif;
#
# Compute difference in error count
VAR_dx := VAR_SSMM_M2_SampleVal - GVAR_SSMM_M2_LastSampleVal;
# Handle wrap-around
if (VAR_dx < 0) then
    VAR_dx := 65535 + VAR_dx;
endif;
#
# Compute delta time
VAR_dt := VAR_SSMM_M2_SampleTime - GVAR_SSMM_M2_LastSampleTime;
#
# Compute gradient
VAR_gradient := VAR_dx/VAR_dt;
#
# Check over a period of at least the sample time (1015 seconds), otherwise return
if (VAR_dt < VAR_CycleTime*VAR_CycleMultiplier) then
    return(GVAR_SSMM_M2_Ok);    
endif;
#
#
# Store this sample & timestamp for next time
GVAR_SSMM_M2_LastSampleTime := VAR_SSMM_M2_SampleTime;
GVAR_SSMM_M2_LastSampleVal := VAR_SSMM_M2_SampleVal;
#
# Calculate the average of the last two points
VAR_avgGrad := (GVAR_SSMM_M2_LastGradient + VAR_gradient)/2;
#
# Store this gradient for the next time
GVAR_SSMM_M2_LastGradient := VAR_gradient;
#
# Return OK/NOK value based on the limits
if (VAR_avgGrad > VAR_LowerLim) land (VAR_avgGrad < VAR_UpperLim) then
    GVAR_SSMM_M2_Ok := 1;
else
    GVAR_SSMM_M2_Ok := 0;
endif;

return(GVAR_SSMM_M2_Ok);
